      piso: c.piso || '',
      telefono: c.telefono || '',
      whatsapp: c.whatsapp || '',
      horario: c.horario || '',
      diasAtencion: Array.isArray(c.diasAtencion) ? c.diasAtencion : [],
      activo: c.activo
    });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({
      nombre: '',
      direccion: '',
      numeroSillones: 1,
      piso: '',
      telefono: '',
      whatsapp: '',
      horario: '',
      diasAtencion: [],
      activo: true
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.nombre.trim()) return;

    if (editingId) {
      updateConsultorio.mutate({ id: editingId, data: formData }, {
