export const NotificationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { token, user } = useAuth();
  const socketRef = useRef<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    if (!token) {
      if (socketRef.current) {
        socketRef.current.disconnect();
        socketRef.current = null;
        setIsConnected(false);
      }
      return;
    }

    // Initialize socket with token
    const socket = io(SOCKET_URL, {
      auth: {
        token,
      },
      transports: ['websocket'],
    });

    socket.on('connect', () => {
      console.log('[Socket] Connected');
      setIsConnected(true);
    });

    socket.on('disconnect', () => {
      console.log('[Socket] Disconnected');
      setIsConnected(false);
    });

    socket.on('connect_error', (error) => {
      console.error('[Socket] Connection error:', error);
      setIsConnected(false);
    });

    // Handle Turno Actualizado
    socket.on('turnoActualizado', (data: { id: string; accion: string; message: string }) => {
      console.log('[Socket] Turno actualizado:', data);

      // Invalidate relevant queries to refresh the UI automatically
      queryClient.invalidateQueries({ queryKey: ['turnos'] });

      // Show toast
      toast.info(data.message, {
        description: `ID: ${data.id.substring(0, 8)}...`,
        duration: 5000,
      });
    });

    socketRef.current = socket;

    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
        socketRef.current = null;
      }
    };
  }, [token]);

  return (
    <NotificationContext.Provider value={{ socket: socketRef.current, isConnected }}>
      {children}
    </NotificationContext.Provider>
  );
};

