            onClose={() => {
              setShowPagoModal(false);
              setSelectedPresupuesto(null);
            }}
            onSubmit={handleRegisterPago}
            loading={registerPago.isPending}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

