export const PresupuestosPage: React.FC = () => {
  const navigate = useNavigate();
  const { id: selectedId } = useParams<{ id: string }>();
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const { data: presupuestosData, isLoading } = usePresupuestos();
  const presupuestos = presupuestosData?.data || [];
  const { createPresupuesto, registerPago } = useFinanzasMutations();

  // Filtrado de presupuestos por Nombre de Paciente
  const filteredPresupuestos = React.useMemo(() => {
    if (!searchTerm.trim()) return presupuestos;
    const term = searchTerm.toLowerCase();
    return presupuestos.filter(p => {
      const pacienteNombre = `${p.paciente?.nombre || ''} ${p.paciente?.apellido || ''}`.toLowerCase();
      return pacienteNombre.includes(term) || p.folio?.toString().includes(term);
    });
  }, [presupuestos, searchTerm]);

  const handleCreate = async (data: any) => {
    try {
      await createPresupuesto.mutateAsync(data);
      setShowCreateModal(false);
    } catch (e) {
      console.error(e);
    }
  };

  const handleRegisterPago = async (data: any) => {
    try {
      await registerPago.mutateAsync(data);
      navigate('/presupuestos');
    } catch (e) {
      console.error(e);
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(value);
  };

  // Only count budgets that have been started (estado === 'iniciado')
  const budgetsIniciados = presupuestos.filter(p => p.estado === 'iniciado');

  const totalFacturado = budgetsIniciados.reduce((acc, p) => acc + Number(p.total), 0);
  const totalPagadoAmount = budgetsIniciados.reduce((acc, p) => acc + Number(p.totalPagado || 0), 0);
  const saldoPendiente = totalFacturado - totalPagadoAmount;

  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.1 }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 10 },
    show: { opacity: 1, y: 0 }
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="show"
      className="flex flex-col gap-8 pb-10"
    >
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div className="space-y-1">
          <motion.h1
            variants={itemVariants}
            className="font-heading text-3xl font-bold tracking-tight text-[var(--sb-text)]"
          >
            Presupuestos y Facturación 💰
          </motion.h1>
          <motion.p
            variants={itemVariants}
            className="text-[var(--sb-text-muted)] font-medium"
          >
            Gestione planes de tratamiento y controle el flujo financiero de su clínica.
          </motion.p>
        </div>

        <motion.button
          variants={itemVariants}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 btn-primary px-6 py-3 rounded-2xl shadow-lg shadow-blue-500/20"
        >
          <Plus size={20} weight="bold" />
          <span className="font-bold tracking-tight">Nuevo Presupuesto</span>
        </motion.button>
      </header>

      {/* Financial Overview Tags */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <PremiumCard delay={0.1}>
          <div className="flex items-center justify-between mb-4">
            <div className="p-2.5 rounded-xl bg-blue-50 dark:bg-blue-500/10">
              <Receipt className="text-blue-600 dark:text-blue-400" size={24} />
            </div>
            <div className="flex items-center gap-1 text-emerald-500 font-bold text-xs">
              <TrendUp size={14} />
              +8%
            </div>
          </div>
          <div className="space-y-1">
            <p className="text-[var(--sb-text-muted)] text-xs font-bold uppercase tracking-wider opacity-70">Total Facturado</p>
            <h3 className="text-2xl font-mono font-bold tracking-tighter text-[var(--sb-text)]">
              {formatCurrency(totalFacturado || 1240000)}
            </h3>
          </div>
        </PremiumCard>

        <PremiumCard delay={0.2}>
          <div className="flex items-center justify-between mb-4">
            <div className="p-2.5 rounded-xl bg-emerald-50 dark:bg-emerald-500/10">
              <Wallet className="text-emerald-600 dark:text-emerald-400" size={24} />
            </div>
            <ArrowUpRight className="text-slate-200 dark:text-slate-800" size={20} />
          </div>
          <div className="space-y-1">
            <p className="text-[var(--sb-text-muted)] text-xs font-bold uppercase tracking-wider opacity-70">Cobros Realizados</p>
            <h3 className="text-2xl font-mono font-bold tracking-tighter text-[var(--sb-text)]">
              {formatCurrency(totalPagadoAmount || 790000)}
            </h3>
          </div>
        </PremiumCard>

        <PremiumCard delay={0.3}>
          <div className="flex items-center justify-between mb-4">
            <div className="p-2.5 rounded-xl bg-amber-50 dark:bg-amber-500/10">
              <ChartPie className="text-amber-600 dark:text-amber-400" size={24} />
            </div>
            <div className="h-2 w-12 bg-amber-200 dark:bg-amber-900/50 rounded-full overflow-hidden">
               <div className="h-full bg-amber-500 w-[60%]" />
            </div>
          </div>
          <div className="space-y-1">
            <p className="text-[var(--sb-text-muted)] text-xs font-bold uppercase tracking-wider opacity-70">Saldo Pendiente</p>
            <h3 className="text-2xl font-mono font-bold tracking-tighter text-[var(--sb-text)]">
              {formatCurrency(saldoPendiente || 450000)}
            </h3>
          </div>
        </PremiumCard>
      </div>

      {/* Main List Section */}
      <motion.div variants={itemVariants} className="space-y-4">
        <div className="flex items-center justify-between gap-4">
          <h2 className="font-heading text-xl font-bold text-[var(--sb-text)] whitespace-nowrap">Listado de Presupuestos</h2>

          <div className="flex items-center gap-4 flex-1 justify-end">
            <div className="relative group max-w-sm w-full">
              <MagnifyingGlass className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--sb-border)] dark:text-slate-600 group-focus-within:text-blue-500 transition-colors" size={18} weight="bold" />
              <input
                type="text"
                placeholder="Buscar por paciente o folio..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-[var(--card-bg)] border-[var(--sb-border)] rounded-xl py-2.5 pl-10 pr-10 text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500/20 border transition-all shadow-sm"
              />
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--sb-border)] hover:text-slate-500 transition-colors"
                >
                  <X size={16} />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2 text-xs font-bold text-[var(--sb-text-muted)] uppercase tracking-widest px-3 py-1.5 bg-[var(--sb-active-bg)]/50 rounded-full whitespace-nowrap">
              <div className="h-2 w-2 rounded-full bg-blue-500 animate-pulse" />
              {filteredPresupuestos.length} Registros
            </div>
          </div>
        </div>

        {filteredPresupuestos.length > 0 ? (
          <PresupuestoList
            presupuestos={filteredPresupuestos}
            isLoading={isLoading}
            onSelect={(p) => navigate(`/presupuestos/${p.id}`)}
          />
        ) : !isLoading && (
          <div className="medical-card p-20 text-center border-dashed border-[var(--sb-border)]">
            <Receipt size={48} className="mx-auto text-[var(--sb-border)] dark:text-slate-800 mb-4" />
            <p className="text-[var(--sb-text-muted)] font-bold uppercase tracking-widest text-[11px]">No se encontraron resultados</p>
            <p className="text-[var(--sb-text-muted)] text-xs mt-2">Intenta con otro término de búsqueda o folio.</p>
          </div>
        )}
      </motion.div>

      {/* Modals */}
      <AnimatePresence>
        {showCreateModal && (
          <PresupuestoForm
            onClose={() => setShowCreateModal(false)}
            onSubmit={handleCreate}
            loading={createPresupuesto.isPending}
          />
        )}

        {selectedId && (
          <PagoModal
            presupuestoId={selectedId}
            onClose={() => navigate('/presupuestos')}
            onSubmit={handleRegisterPago}
            loading={registerPago.isPending}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
};

