        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          if (onClick) onClick();
        }
      }}
      tabIndex={0}
      role="button"
      aria-label={`Pieza dental ${etiquetaPieza(posicion, sistemaDental)}${selected ? ', seleccionada' : ''}`}
