        {etiquetaPieza(posicion, sistemaDental)}
      </span>

      <svg 
        width="46" 
        height="46" 
        viewBox="0 0 60 60"
        role="img"
        aria-label={`Estado de caras de la pieza ${etiquetaPieza(posicion, sistemaDental)}`}
      >
        {/* Border / Outer Shape */}
        <rect x="5" y="5" width="50" height="50" fill="none" stroke="#ddd" strokeWidth="1" />

