        </div>
          <div className="px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest"
          style={{ background: 'var(--sb-active-bg)', color: 'var(--sb-text-muted)' }}>
          {meta?.total || 0} Registros Encontrados
